def validate_topics():
    print(f"Validating UHS_MBBS topics: count = {len(UHS_MBBS_TOPICS)}")
    assert len(UHS_MBBS_TOPICS) == 100, f"Expected 100 UHS_MBBS topics, got {len(UHS_MBBS_TOPICS)}"
    for idx, item in enumerate(UHS_MBBS_TOPICS):
        title, subj, sys, hallmark, ref_lbl, ref_url = item
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at UHS_MBBS #{idx+1}: {title}"
        assert sys in TAXONOMY_SYSTEMS, f"Invalid system {sys} at UHS_MBBS #{idx+1}: {title}"
        assert len(title) >= 10, f"Title too short at UHS_MBBS #{idx+1}"
        assert len(hallmark) >= 15, f"Hallmark too short at UHS_MBBS #{idx+1}"
        assert ref_url.startswith("https://"), f"Invalid ref_url at UHS_MBBS #{idx+1}"
    print("  -> All 100 UHS_MBBS topics PASSED validation!")

    print(f"Validating PLAB topics: count = {len(PLAB_TOPICS)}")
    assert len(PLAB_TOPICS) == 100, f"Expected 100 PLAB topics, got {len(PLAB_TOPICS)}"
    for idx, item in enumerate(PLAB_TOPICS):
        title, subj, sys, hallmark, ref_lbl, ref_url = item
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at PLAB #{idx+1}: {title}"
        assert sys in TAXONOMY_SYSTEMS, f"Invalid system {sys} at PLAB #{idx+1}: {title}"
        assert len(title) >= 10, f"Title too short at PLAB #{idx+1}"
        assert len(hallmark) >= 15, f"Hallmark too short at PLAB #{idx+1}"
        assert ref_url.startswith("https://"), f"Invalid ref_url at PLAB #{idx+1}"
    print("  -> All 100 PLAB topics PASSED validation!")

def export_topics():
    out_file = os.path.join(os.path.dirname(__file__), "mega90_topics_a.py")
    with open(out_file, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 90 Part A topics (UHS_MBBS 100, PLAB 100)\n\n")
        f.write("UHS_MBBS_TOPICS = " + json.dumps(UHS_MBBS_TOPICS, indent=2) + "\n\n")
        f.write("PLAB_TOPICS = " + json.dumps(PLAB_TOPICS, indent=2) + "\n")
    print(f"Successfully generated {out_file} with 200 topics!")

if __name__ == "__main__":
    validate_topics()
    export_topics()
